const rows = $input.first().json;
const list = Array.isArray(rows) ? rows : [];
const now = new Date();
const outputs = [];
function fmtDate(iso, tz) {
  return new Intl.DateTimeFormat('en-US', { timeZone: tz || 'America/Toronto', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(new Date(iso));
}
function fmtTime(iso, tz) {
  return new Intl.DateTimeFormat('en-US', { timeZone: tz || 'America/Toronto', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' }).format(new Date(iso));
}
const subjects = {
  confirmation: 'Your Revenue Leak Audit Is Confirmed',
  three_day: 'Quick note before our audit',
  one_day: "Tomorrow's Revenue Leak Audit",
  thirty_minute: 'Starting in 30 minutes',
  fifteen_minute: 'Starting shortly'
};
function copy(type, b, eventDate, eventTime) {
  if (type === 'confirmation') return {
    intro: 'Your Revenue Leak Audit has been scheduled.',
    bullets: ['how inquiries and consultations are currently managed', 'where potential opportunities may be slipping through', 'how follow-up is currently handled', 'which opportunities may deserve attention first'],
    close: "This is a working session focused on your clinic's revenue recovery process, not a software demonstration."
  };
  if (type === 'three_day') return {
    intro: 'Looking forward to our upcoming Revenue Leak Audit.',
    bullets: ['monthly inquiry volume', 'consultation volume', 'current no-show process', 'how inactive clients are currently followed up', 'what system your team currently uses for booking and follow-up'],
    close: 'No preparation is required. Rough answers are enough.'
  };
  if (type === 'one_day') return {
    intro: 'Just a reminder that your Revenue Leak Audit is scheduled for tomorrow.',
    bullets: [],
    close: "We'll review your current follow-up process, where opportunities may be slipping through, and what a prioritized Revenue Recovery List could look like."
  };
  if (type === 'thirty_minute') return { intro: 'Your Revenue Leak Audit starts in 30 minutes.', bullets: [], close: 'See you shortly.' };
  return { intro: 'Your Revenue Leak Audit starts in 15 minutes.', bullets: [], close: 'See you shortly.' };
}
function htmlEmail(type, b, eventDate, eventTime, meetingLink) {
  const c = copy(type, b, eventDate, eventTime);
  const bulletHtml = c.bullets.length ? `<ul style="margin:16px 0 0;padding-left:20px;color:#473642;line-height:1.7;">${c.bullets.map(x => `<li>${x}</li>`).join('')}</ul>` : '';
  return `<!doctype html><html><body style="margin:0;background:#fff7fb;font-family:Arial,Helvetica,sans-serif;color:#24171e;"><div style="max-width:620px;margin:0 auto;padding:28px 16px;"><div style="background:#fffdf9;border:1px solid #ead8cd;border-radius:18px;overflow:hidden;box-shadow:0 20px 56px rgba(117,72,90,.10);"><div style="padding:22px 24px;border-bottom:1px solid #ead8cd;"><div style="color:#9d2f5d;font-weight:800;font-size:18px;">MedSpa Growth Engine</div><div style="color:#765063;font-size:12px;margin-top:4px;letter-spacing:.08em;text-transform:uppercase;">Revenue Leak Audit</div></div><div style="padding:26px 24px;line-height:1.65;"><p style="margin:0 0 16px;">Hi ${b.first_name || 'there'},</p><p style="margin:0 0 16px;">${c.intro}</p><div style="background:#fff7fb;border:1px solid #ead8cd;border-radius:14px;padding:16px;margin:20px 0;"><div><strong>Date:</strong> ${eventDate}</div><div><strong>Time:</strong> ${eventTime}</div></div>${bulletHtml}<p style="margin:18px 0 0;">${c.close}</p><div style="margin:24px 0;"><a href="${meetingLink}" style="display:inline-block;background:#9d2f5d;color:#fff;text-decoration:none;font-weight:800;padding:13px 18px;border-radius:10px;">Join Audit</a></div><p style="margin:0;">Looking forward to speaking with you.</p><p style="margin:10px 0 0;">- Ishan</p></div><div style="padding:16px 24px;border-top:1px solid #ead8cd;color:#765063;font-size:12px;line-height:1.5;">This reminder is for your scheduled Revenue Leak Audit. No preparation is required.</div></div></div></body></html>`;
}
function textEmail(type, b, eventDate, eventTime, meetingLink) {
  const c = copy(type, b, eventDate, eventTime);
  const bullets = c.bullets.map(x => `- ${x}`).join('\n');
  return `Hi ${b.first_name || 'there'},\n\n${c.intro}\n\nDate: ${eventDate}\nTime: ${eventTime}\n\n${bullets ? bullets + '\n\n' : ''}${c.close}\n\nMeeting link:\n${meetingLink}\n\nLooking forward to speaking with you.\n\n- Ishan`;
}
for (const row of list) {
  const b = row.audit_bookings || row.booking || {};
  const eventStart = b.event_start_time ? new Date(b.event_start_time) : null;
  if (!b.id || b.status !== 'scheduled' || !eventStart || eventStart <= now) {
    outputs.push({ json: { action: 'skip', log_id: row.id, reason: 'Booking cancelled, missing, or event already started' } });
    continue;
  }
  if (!b.email || !b.meeting_link) {
    outputs.push({ json: { action: 'fail', log_id: row.id, error_message: 'Missing invitee email or meeting link' } });
    continue;
  }
  const eventDate = fmtDate(b.event_start_time, b.event_timezone);
  const eventTime = fmtTime(b.event_start_time, b.event_timezone);
  outputs.push({ json: { action: 'send', log_id: row.id, booking_id: b.id, reminder_type: row.reminder_type, to: b.email, subject: subjects[row.reminder_type] || 'Revenue Leak Audit Reminder', html: htmlEmail(row.reminder_type, b, eventDate, eventTime, b.meeting_link), text: textEmail(row.reminder_type, b, eventDate, eventTime, b.meeting_link) } });
}
return outputs;

const emailItem = $('Prepare Due Emails').item.json;
const result = $input.first().json || {};
const failed = !!result.error || !!result.message?.includes?.('error');
return [{ json: { log_id: emailItem.log_id, status: failed ? 'failed' : 'sent', sent_at: failed ? null : new Date().toISOString(), provider_message_id: result.id || result.messageId || result.threadId || null, error_message: failed ? JSON.stringify(result.error || result).slice(0, 900) : null } }];
